solution:
.form {
  padding: 20px;
  border: 2px dashed #a1a1aa;
}

.form label {
  font-weight: 600;
}

.field {
  box-sizing: border-box;
  padding: 8px 10px;
  border: 1px solid #a1a1aa;
  border-radius: 4px;
}

.submit {
  padding: 8px 16px;
  border: 0;
  border-radius: 4px;
  background: #f97316;
  color: #fff;
}

/* ---- Solution ---- */
.form {
  display: grid;
  grid-template-columns: 100px 1fr;
  gap: 12px 16px;
  align-items: center;
}

.submit {
  grid-column: 2;
  justify-self: start;
}

@media (max-width: 500px) {
  .form {
    grid-template-columns: 1fr;
    gap: 6px;
  }

  .submit {
    grid-column: auto;
    margin-top: 6px;
  }
}
